// Throwaway: capture US-02 AC-18 evidence (step 2 at 360x740 and 1280x800, CO and CL).
// Seeds a valid, fictitious step 1 into sessionStorage (ADR-0003 entry), then opens /<cc>/planes.
const path = require('node:path');
const { chromium } = require(path.resolve(process.argv[2], 'frontend/node_modules/playwright'));
const outDir = path.resolve(process.argv[2], 'docs/qa/US-02');

const step1 = {
  co: { documentType: 'CC', documentNumber: '1012345678', fullName: 'Ana Prueba Ficticia', birthDate: '1990-05-15',
        city: 'MDE', plate: 'ABC123', make: 'chevrolet', model: 'Spark GT', vehicleYear: '2020', dataConsent: true },
  cl: { documentNumber: '12.345.678-5', fullName: 'Pedro Prueba Ficticio', birthDate: '1988-03-10',
        city: 'SCL', plate: 'BCDF12', make: 'suzuki', model: 'Swift', vehicleYear: '2019', dataConsent: true },
};

(async () => {
  const browser = await chromium.launch();
  for (const [cc, values] of Object.entries(step1)) {
    for (const [w, h] of [[360, 740], [1280, 800]]) {
      const page = await browser.newPage({ viewport: { width: w, height: h } });
      await page.goto('http://localhost:8080/');
      await page.evaluate(([country, vals]) => sessionStorage.setItem('quote-wizard',
        JSON.stringify({ version: 1, country, step1: { values: vals } })), [cc.toUpperCase(), values]);
      await page.goto(`http://localhost:8080/${cc}/planes`);
      await page.getByRole('heading', { level: 1, name: 'Elige tu plan' }).waitFor({ timeout: 15000 });
      await page.getByRole('radio').first().waitFor();
      const url = page.url(); const radios = await page.getByRole('radio').count();
      const hScroll = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
      const file = path.join(outDir, `ac-18-${cc}-step2-${w}x${h}.png`);
      await page.screenshot({ path: file, fullPage: true });
      console.log(`${cc} ${w}x${h}: url=${new URL(url).pathname} plans=${radios} horizontalScroll=${hScroll} -> ${path.basename(file)}`);
      await page.close();
    }
  }
  await browser.close();
})().catch((e) => { console.error('CAPTURE FAILED:', e.message); process.exit(1); });

