// Throwaway: capture US-03 AC-18 evidence (CO summary and confirmation at 360x740 and 1280x800).
// Seeds a valid, fictitious step 1 and a chosen plan into sessionStorage (ADR-0003 entry), opens
// /co/resumen, accepts the terms with the keyboard, pays with the default simulated outcome
// ("Pago aprobado") and captures the confirmation. Also captures CL summary at both sizes.
const path = require('node:path');
const { chromium } = require(path.resolve(process.argv[2], 'frontend/node_modules/playwright'));
const outDir = path.resolve(process.argv[2], 'docs/qa/US-03');

const states = {
  co: { plan: 'clasico', values: { documentType: 'CC', documentNumber: '1012345678', fullName: 'Ana Prueba Ficticia',
        birthDate: '1990-05-15', city: 'MDE', plate: 'ABC123', make: 'chevrolet', model: 'Spark GT', vehicleYear: '2020', dataConsent: true } },
  cl: { plan: 'protegido', values: { documentNumber: '12.345.678-5', fullName: 'Pedro Prueba Ficticio', birthDate: '1988-03-10',
        city: 'SCL', plate: 'BCDF12', make: 'suzuki', model: 'Swift', vehicleYear: '2019', dataConsent: true } },
};

async function check(page, label) {
  const hScroll = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
  console.log(`${label}: url=${new URL(page.url()).pathname} horizontalScroll=${hScroll}`);
}

(async () => {
  const browser = await chromium.launch();
  for (const [cc, st] of Object.entries(states)) {
    for (const [w, h] of [[360, 740], [1280, 800]]) {
      const page = await browser.newPage({ viewport: { width: w, height: h } });
      await page.goto('http://localhost:8080/');
      await page.evaluate(([country, s]) => sessionStorage.setItem('quote-wizard',
        JSON.stringify({ version: 1, country, step1: { values: s.values }, plan: { key: s.plan } })), [cc.toUpperCase(), st]);
      await page.goto(`http://localhost:8080/${cc}/resumen`);
      await page.getByRole('heading', { level: 1, name: 'Resumen de tu cotización' }).waitFor({ timeout: 15000 });
      await page.getByRole('checkbox', { name: 'Acepto los términos y condiciones' }).waitFor();
      await check(page, `${cc} ${w}x${h} summary`);
      await page.screenshot({ path: path.join(outDir, `ac-18-${cc}-summary-${w}x${h}.png`), fullPage: true });
      if (cc === 'co') {
        await page.getByRole('checkbox', { name: 'Acepto los términos y condiciones' }).check();
        await page.getByRole('button', { name: 'Pagar' }).click();
        await page.getByRole('heading', { level: 1, name: 'Pago confirmado' }).waitFor({ timeout: 15000 });
        const stored = await page.evaluate(() => sessionStorage.getItem('quote-wizard'));
        await check(page, `${cc} ${w}x${h} confirmation (stored entry: ${stored === null ? 'none' : 'PRESENT'})`);
        await page.screenshot({ path: path.join(outDir, `ac-18-${cc}-confirmation-${w}x${h}.png`), fullPage: true });
      }
      await page.close();
    }
  }
  await browser.close();
})().catch((e) => { console.error('CAPTURE FAILED:', e.message); process.exit(1); });

